from pathlib import Path
import re

root = Path('.')
app = root / 'src/client/PremiumApp.tsx'
s = app.read_text()

replacement = r'''function ManagerOrderPage() {
  const { id = '' } = useParams();
  const [order, setOrder] = useState<OrderSummary | null>(null);
  const [ops,setOps]=useState({assignedManager:'',pickupNote:'',internalNote:'',lastContactAt:null as string|null,updatedAt:null as string|null});
  const [workflow,setWorkflow]=useState({operationType:'none',requestedDate:'',reason:'',managerNote:'',workflowStatus:'Нет запроса',updatedAt:null as string|null});
  const [error, setError] = useState(''); const [saved,setSaved]=useState(false); const [workflowSaved,setWorkflowSaved]=useState(false); const [workflowBusy,setWorkflowBusy]=useState(false);
  const load = () => { void Promise.all([api.managerOrder(id),api.managerOps(id),api.orderWorkflow(id)]).then(([orderResult,opsResult,workflowResult])=>{setOrder(orderResult.order);setOps(opsResult.ops);setWorkflow(workflowResult.workflow)}).catch((e) => setError(e.message)); };
  useEffect(() => { load(); }, [id]);
  const update = async (status: OrderSummary['status']) => { const result = await api.managerStatus(id, status); setOrder(result.order); };
  const saveOps=async(markContacted=false)=>{const result=await api.patchManagerOps(id,{...ops,markContacted});setOps(result.ops);setSaved(true);setTimeout(()=>setSaved(false),1600)};
  const chooseOperation=(operationType:'none'|'reschedule'|'cancel')=>setWorkflow(current=>({...current,operationType,requestedDate:operationType==='reschedule'?current.requestedDate:'',workflowStatus:operationType==='none'?'Нет запроса':'Запрошено'}));
  const saveWorkflow=async()=>{setWorkflowBusy(true);setError('');try{const result=await api.patchOrderWorkflow(id,workflow);setWorkflow(result.workflow);setWorkflowSaved(true);setTimeout(()=>setWorkflowSaved(false),1800)}catch(e:any){setError(e.message||'Не удалось сохранить операцию')}finally{setWorkflowBusy(false)}};
  if (error && !order) return <Notice>{error}</Notice>; if (!order) return <SkeletonCards />;
  const workflowLabels:Record<string,string>={none:'Без операции',reschedule:'Перенос',cancel:'Отмена'};
  return <>
    <section className="px-order-detail-grid"><Detail label="Экскурсия" value={order.tourTitle} /><Detail label="Дата" value={order.selectedDate} /><Detail label="Клиент" value={order.customer} /><Detail label="Контакт" value={order.contact} /><Detail label="Отель" value={order.hotel} /><Detail label="Источник" value={order.source} /><Detail label="Сумма" value={formatUsd(order.totalMinor)} /><Detail label="Оплачено" value={formatUsd(order.paidMinor)} /><Detail label="Осталось" value={formatUsd(order.remainingMinor)} /></section>
    <section className="px-section px-office-actions"><h2>Статус заказа</h2><div>{(['Новый', 'Оплачено', 'Подтверждено'] as OrderSummary['status'][]).map((status) => <button key={status} className={order.status === status ? 'active' : ''} onClick={() => update(status)}>{status}</button>)}</div><p>Статус сохраняется в D1, фиксируется в журнале действий и сразу виден владельцу.</p></section>
    <section className="px-section px-manager-editor"><div><span className="px-kicker">РАБОТА МЕНЕДЖЕРА</span><h2>Исполнение заказа</h2><p>Менеджер отвечает за коммуникацию, точку сбора и внутренние детали. Цена и программа остаются зоной администратора.</p></div><label className="px-field"><span>Ответственный менеджер</span><select value={ops.assignedManager} onChange={e=>setOps({...ops,assignedManager:e.target.value})}><option value="">Не назначен</option><option>Менеджер 1</option><option>Менеджер 2</option><option>Менеджер 3</option></select></label><label className="px-field"><span>Трансфер / точка сбора</span><input value={ops.pickupNote} onChange={e=>setOps({...ops,pickupNote:e.target.value})} placeholder="Уточнение по отелю и времени" /></label><label className="px-field"><span>Внутренняя заметка</span><textarea rows={5} value={ops.internalNote} onChange={e=>setOps({...ops,internalNote:e.target.value})} placeholder="Что важно передать следующей смене или гиду" /></label><div className="px-manager-edit-actions"><button className="px-button px-button-dark" onClick={()=>saveOps(false)}>{saved?'Сохранено ✓':'Сохранить изменения'}</button><button className="px-button px-button-primary" onClick={()=>saveOps(true)}>Связались с клиентом</button></div>{ops.lastContactAt&&<p className="px-form-note">Последний контакт: {new Date(ops.lastContactAt).toLocaleString('ru-RU')}</p>}</section>
    <section className="px-section px-order-workflow"><div className="px-workflow-head"><div><span className="px-kicker">ПЕРЕНОС / ОТМЕНА · DEMO</span><h2>Изменение поездки</h2><p>Внутренний workflow уже работает в D1. Он фиксирует запрос и решение менеджера, не подменяя реальный возврат средств.</p></div><span className="px-workflow-state">{workflow.workflowStatus}</span></div><div className="px-workflow-choice">{(['none','reschedule','cancel'] as const).map(type=><button key={type} className={workflow.operationType===type?'active':''} onClick={()=>chooseOperation(type)}><b>{workflowLabels[type]}</b><span>{type==='none'?'Обычное исполнение':type==='reschedule'?'Новая дата поездки':'Запрос на отмену'}</span></button>)}</div>{workflow.operationType!=='none'&&<div className="px-workflow-editor">{workflow.operationType==='reschedule'&&<label className="px-field"><span>Новая желаемая дата</span><input type="date" value={workflow.requestedDate} onChange={e=>setWorkflow({...workflow,requestedDate:e.target.value})}/></label>}<label className="px-field"><span>Причина / запрос клиента</span><textarea rows={3} value={workflow.reason} onChange={e=>setWorkflow({...workflow,reason:e.target.value})} placeholder={workflow.operationType==='cancel'?'Почему клиент просит отмену':'Почему нужен перенос'}/></label><label className="px-field"><span>Решение / заметка менеджера</span><textarea rows={3} value={workflow.managerNote} onChange={e=>setWorkflow({...workflow,managerNote:e.target.value})} placeholder="Что согласовано, что нужно проверить"/></label><label className="px-field"><span>Статус согласования</span><select value={workflow.workflowStatus} onChange={e=>setWorkflow({...workflow,workflowStatus:e.target.value})}><option>Запрошено</option><option>Согласовано</option><option>Отклонено</option></select></label>{workflow.operationType==='cancel'&&order.paidMinor>0&&<div className="px-workflow-warning"><b>Оплата уже зафиксирована: {formatUsd(order.paidMinor)}</b><span>DEMO-отмена не создаёт фиктивный refund. Возврат будет выполняться только через реальный платёжный провайдер после интеграции.</span></div>}</div>}<button className="px-button px-button-dark px-block" disabled={workflowBusy} onClick={saveWorkflow}>{workflowBusy?'Сохраняем…':workflowSaved?'Операция сохранена ✓':'Сохранить операцию'}</button>{workflow.updatedAt&&<p className="px-form-note">Последнее изменение: {new Date(workflow.updatedAt).toLocaleString('ru-RU')} · записано в audit log владельца.</p>}{error&&<Notice>{error}</Notice>}</section>
  </>;
}

function ChannelsPage'''

pattern = r"function ManagerOrderPage\(\) \{.*?\n\}\n\nfunction ChannelsPage"
s, count = re.subn(pattern, replacement, s, count=1, flags=re.S)
if count != 1:
    raise SystemExit('ManagerOrderPage replacement failed')
app.write_text(s)

css_path = root / 'src/client/styles/premium.css'
css = css_path.read_text()
marker = '/* INTERNAL_COMPLETION_UI_V4 */'
if marker not in css:
    css += r'''
/* INTERNAL_COMPLETION_UI_V4 */
.px-order-workflow{display:grid;gap:18px;margin-top:8px;padding:24px;border:1px solid var(--px-line);border-radius:24px;background:var(--px-paper);box-shadow:0 14px 38px rgba(18,32,27,.06)}.px-workflow-head{display:flex;justify-content:space-between;align-items:start;gap:18px}.px-workflow-head h2{font-family:Georgia,"Times New Roman",serif;font-size:32px;font-weight:500;line-height:1.04;margin:8px 0}.px-workflow-head p{margin:0;color:var(--px-muted);font-size:12px;line-height:1.55;max-width:620px}.px-workflow-state{flex:none;border:1px solid var(--px-line);border-radius:999px;background:#fff;padding:8px 11px;font-size:10px;font-weight:800}.px-workflow-choice{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.px-workflow-choice button{border:1px solid var(--px-line);border-radius:16px;background:#fff;padding:14px;text-align:left;display:grid;gap:4px;cursor:pointer}.px-workflow-choice button.active{background:var(--px-green);border-color:var(--px-green);color:#fff}.px-workflow-choice b{font-size:13px}.px-workflow-choice span{font-size:10px;opacity:.7;line-height:1.35}.px-workflow-editor{display:grid;gap:12px;padding:16px;border-radius:18px;background:#f0ece3}.px-workflow-warning{display:grid;gap:5px;padding:14px;border-radius:14px;background:#fff4dd;border:1px solid rgba(151,102,23,.18)}.px-workflow-warning b{font-size:12px}.px-workflow-warning span{font-size:11px;line-height:1.5;color:#6f5a34}.px-audit-list{display:grid;margin-top:16px;border-top:1px solid var(--px-line)}.px-audit-list>div{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid var(--px-line)}.px-audit-list b{font-size:12px}.px-audit-list p{margin:4px 0 0;color:var(--px-muted);font-size:10px}.px-audit-list time{font-size:9px;color:var(--px-muted);text-align:right}.px-audit-role{border-radius:999px;padding:6px 8px;background:#eee8dc;font-size:8px;font-weight:900;text-transform:uppercase}.px-owner-audit-head{display:flex;align-items:center;justify-content:space-between;gap:14px}.px-owner-audit-head h3{margin:8px 0 0}.px-crm-edit-toggle{width:100%;border:0;background:#eee8dc;border-radius:12px;padding:11px 12px;text-align:left;font-size:11px;font-weight:700;cursor:pointer;margin-top:10px}.px-crm-editor{display:grid;gap:12px;margin-top:12px;padding:14px;border:1px solid var(--px-line);border-radius:16px;background:#f6f2ea}.px-crm-task-row{display:grid;grid-template-columns:1fr auto;gap:12px;align-items:end}.px-crm-task-row .px-owner-check{margin-bottom:8px}.px-integration-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:22px}.px-integration-grid article{border:1px solid var(--px-line);border-radius:20px;background:var(--px-paper);padding:18px;display:grid;gap:8px}.px-integration-grid article span{font-size:8px;font-weight:900;letter-spacing:.12em;color:var(--px-green-2)}.px-integration-grid article h3{font-family:Georgia,serif;font-size:22px;font-weight:500;margin:0}.px-integration-grid article p,.px-integration-grid article b{font-size:11px;line-height:1.5;margin:0}.px-integration-grid article b{color:var(--px-muted)}
@media(max-width:680px){.px-workflow-head{display:grid}.px-workflow-choice{grid-template-columns:1fr}.px-audit-list>div{grid-template-columns:auto 1fr}.px-audit-list time{grid-column:2;text-align:left}.px-owner-audit-head{align-items:flex-start;display:grid}.px-crm-task-row{grid-template-columns:1fr}.px-integration-grid{grid-template-columns:1fr}.px-order-workflow{padding:18px}}
'''
    css_path.write_text(css)

print('internal UI v4 completed')
